```python
def flatten(nested):
    flat_list = []
    for item in nested:
        if isinstance(item, list):
            flat_list.extend(flatten(item))
        else:
            flat_list.append(item)
    return flat_list
```

```python
def word_count(text):
    from collections import defaultdict
    words = text.split()
    count = defaultdict(int)
    for word in words:
        count[word] += 1
    return dict(count)

# Example usage:
text = "hello world hello"
print(word_count(text))  # Output: {'hello': 2, 'world': 1}
```

